/**
 * Monday.com Node - Version 2
 * Discriminator: resource=item, operation=moveItem
 */


interface Credentials {
  mondayComApi: CredentialReference;
  mondayComOAuth2Api: CredentialReference;
}

/** Move an item to another group, or to another board with column mapping */
export type MondayComV2ItemMoveItemParams = {
  resource: 'item';
  operation: 'moveItem';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The board to operate on
 * @searchListMethod searchBoards
 * @default {"mode":"list","value":""}
 */
    boardId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The item to operate on
 * @searchListMethod searchItems
 * @default {"mode":"list","value":""}
 */
    itemId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Move To
 * @default group
 */
    moveDestination?: 'board' | 'group';
/**
 * The group to move the item to. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
 * @loadOptionsMethod getBoardGroups
 * @displayOptions.show { moveDestination: ["group"] }
 * @required when the displayOptions conditions above match
 */
    targetGroupId?: string | Expression<string>;
/**
 * The board to move the item to
 * @searchListMethod searchBoards
 * @displayOptions.show { moveDestination: ["board"] }
 * @default {"mode":"list","value":""}
 */
    targetBoardId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The group on the target board to move the item to. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
 * @loadOptionsMethod getTargetBoardGroups
 * @displayOptions.show { moveDestination: ["board"] }
 * @required when the displayOptions conditions above match
 */
    targetBoardGroupId?: string | Expression<string>;
/**
 * How source columns map to target-board columns. Unmapped columns lose their values on cross-board moves.
 * @displayOptions.show { moveDestination: ["board"] }
 * @default {}
 */
    columnsMappingUi?: {
        /** Mapping
     */
    mappings?: Array<{
      /** The column on the item's current board. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
       * @loadOptionsMethod getBoardColumns
       */
      source?: string | Expression<string>;
      /** The column on the target board that receives the value. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
       * @loadOptionsMethod getTargetBoardColumns
       */
      target?: string | Expression<string>;
    }>;
  };
/**
 * Options
 * @displayOptions.show { moveDestination: ["board"] }
 * @default {}
 */
    moveOptions?: {
    /** How source columns map to target-board columns, as [{"source": "columnId", "target": "columnId"}] — an expression-friendly alternative to the Columns Mapping rows above. Ignored when any mapping rows are configured.
     * @default []
     */
    columnsMapping?: IDataObject | string | Expression<string>;
  };
};

export type MondayComV2ItemMoveItemNode = {
  type: 'n8n-nodes-base.mondayCom';
  version: 2;
  config: NodeConfig<MondayComV2ItemMoveItemParams> & { credentials?: Credentials };
};